---InitSortTypeList
---根据类型提取筛选数据
---@param kind number
function UIAreaFilterMB:InitSortTypeList(kind,isShowAll)
    if self.sortTypeList then return end
    local row = CfUtils.GetCfLine(AutoIds.IdSetting47, kind)
    local types = parse_strings(parse_localizeText(row, "name"))
    local conditions = parse_strings(parse_string(row, "condition"))
    local sortTypeList = {}
    if isShowAll then
        local srcTxt = localize('全部')
        sortTypeList = {{sortTypeId = 888, name = srcTxt}}
    end
    for i, sortTypeId in ipairs(conditions) do
        table.insert(sortTypeList, {sortTypeId = checkNumber(sortTypeId), name = tostring(types[i])})
    end
    self.sortTypeList = sortTypeList
end

function UIAreaFilterMB:InitAlignDropDown(selectIndex)
    if not self.isInitDropDown then
        return
    end

    self:InitAlignDropDownAction()

    local AlignDropDown = self.AlignDropDown
    local AlignCell = self.AlignCell
    local alignCellList = {}
    local sortTypeList  = self.sortTypeList
    local cellCount = 1
    local sortTypeCount = table.count(sortTypeList)

    local forTimes = math.max(sortTypeCount, cellCount)
    for i = 1, forTimes do
        local sortTypeData = sortTypeList[i]
        local alignCell    = alignCellList[i]
        if sortTypeData then
            if alignCell == nil then
                alignCell = AlignDropDown.gameObject:AddChild(AlignCell.gameObject)
                alignCellList[i] = alignCell
            end

            local script = GetLuaBehaviour(alignCell, UICommonFilterAlignCellPath)
            ---@type UICommonFilterAlignCell
            local cellEnv = script.Env
            if cellEnv == nil then
                script:Init()
                cellEnv = script.Env
            end

            if cellEnv then
                cellEnv:RefreshUI(i, true, sortTypeData.name,2)
                KTool.SetActive(alignCell.gameObject, true)
                KTool.SetActive(cellEnv.Image.gameObject, false)
                cellEnv:SetCallback(Bind(self, self.OnClickAlignCellAction))
                cellEnv:RefreshSelectState(selectIndex == i)
            end

        elseif alignCell then
            KTool.SetActive(alignCell.gameObject, false)
        end

    end

    self.alignCellList = alignCellList
    self.isInitDropDown = nil

end

function UIAreaFilterMB:InitAlignDropDownAction()
    local behaviourAction = KTool.GetOrAddComponent(self.AlignDropDown.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = Bind(self, self.Update)
        self._behaviourAction = behaviourAction
    end
end

function UIAreaFilterMB:Update()
    if Utils.TouchCount() > 0 and (not self.__closing) then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self.AlignDropDown.transform, position,
                    self.uiRenderCamera or UIModule.RootCanvas.canvas.worldCamera)
            if not isInRect then
                ---不在区域中
                KTool.SetActive(self.AlignDropDown.gameObject, false)
            end
        end
    end
end

function UIAreaFilterMB:InitAction()
    UIEventProxy.Create(self.AlignButton.gameObject).onPointerClick  = Bind(self, self.OnClickAlignButtonAction)
end

