function UIAreaFilterMB:OnClickAlignButtonAction()
    KTool.SetActive(self.AlignDropDown.gameObject, true)
    self:InitAlignDropDown(self.selectIndex)
end



function UIAreaFilterMB:OnClickAlignCellAction(index)
    if self.selectIndex == index then return end
    --- 这里只更新 老的cell 选择状态 当前选择状态根据返回值 刷新
    local oldCell = self.alignCellList[self.selectIndex]

    ---@type UICommonFilterAlignCell
    local cellEnv = CfUtils.GetLuaScr(oldCell, UICommonFilterAlignCellPath)
    if cellEnv then
        cellEnv:RefreshSelectState(false)
    end

    self.selectIndex = index

    self:RefreshUI()

    return true
end

function UIAreaFilterMB:OnCloseFilterButtonAction()
    KTool.SetActive(self.CloseButton.gameObject, false)
    self.groups = {}
    self.filterData = nil
    self.selectIndex = 1
    self:RefreshUI()
end

